"""Mazes are lists of strings. '#' is a wall; '.', 'S' and 'E' are open floor.

'>', '<', '^' and 'v' are conveyor tiles: you may step onto one from any side,
but you can only leave it in the direction it points.
"""

ARROWS = {">": (0, 1), "<": (0, -1), "^": (-1, 0), "v": (1, 0)}
STEPS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def find(grid, ch):
    for r, row in enumerate(grid):
        c = row.find(ch)
        if c != -1:
            return (r, c)
    raise ValueError("no %r in maze" % ch)


def neighbours(grid, cell):
    """The cells you can move to from cell in one step."""
    r, c = cell
    here = grid[r][c]
    moves = [ARROWS[here]] if here in ARROWS else STEPS
    out = []
    for dr, dc in moves:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(grid) and 0 <= nc < len(grid[nr]) and grid[nr][nc] != "#":
            out.append((nr, nc))
    return out

