import unittest

from solver import solve


class Regression(unittest.TestCase):
    def test_a_walled_off_goal_is_unreachable(self):
        maze = ["S.#..", "..#..", "###..", "....E"]
        self.assertIsNone(solve(maze))

    def test_conveyors_only_carry_you_one_way(self):
        self.assertEqual(solve(["E<S"]), 2)
        self.assertIsNone(solve(["E>S"]))

    def test_the_route_goes_around_a_wall(self):
        maze = ["S#...", ".#.#.", ".#.#.", "...#E"]
        self.assertEqual(solve(maze), 13)

    def test_a_large_open_floor(self):
        floor = ["S" + "." * 29] + ["." * 30] * 28 + ["." * 29 + "E"]
        self.assertEqual(solve(floor), 58)

