class SearchLimitExceeded(Exception):
    pass


def shortest_path_length(grid, start, end):
    """Moves on the shortest route from start to end, or None if end cannot be reached."""
    queue = deque([(start, 0)])
    # Mark a cell when it is queued, so no cell is ever queued twice. Each cell is then
    # visited at most once, and the number of steps can never exceed the number of cells.
    seen = {start}
    steps = 0
    while queue:
        steps += 1
        if steps > MAX_STEPS:
            raise SearchLimitExceeded("gave up after %d steps" % MAX_STEPS)
        cell, dist = queue.popleft()
        if cell == end:
            return dist
        for nxt in neighbours(grid, cell):
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, dist + 1))
    return None


def solve(grid):
    return shortest_path_length(grid, find(grid, "S"), find(grid, "E"))

